import sys
sys.dont_write_bytecode=True
import additional_pfp_tests_remaining_audit as a
ep='pfp/tests/evaluators/test_levels_11_21_evaluator_traits.py';wp='pfp/tests/workflows/test_multi_agent_dialogue_workflows.py'
a.record(ep,1,1180,'Full1180line body read in four chunks. Defines its own toy evaluators rather than importing canonical production validators. ARS depth cutoff is incorrectly called normal form and len(NFs)<=1 certifies even nonjoinable cyclic peaks. DDA hashes only6of13fields with64bit truncated digest, uses supplied nonnegative metrics and2fiber names rather than semantic observer adequacy. Alternation counts unequal strings with unchecked negative budgets; RGB trusts Boolean syntax/gauge flags; authority gate trusts Boolean verifier/deletion flags. Ind-object checks finite set inclusions and future single characters, ignores allowed_depth/unknown symbols and any universal colimit property. Dialect gate hashes payload and only alphabetchecks SymBin; no other grammars. Hodge checks supplied vector sum/pairwise Euclidean orthogonality/gap0, not boundary images, harmonic kernel or LP feasibility. Ihara ignores spectrum and accepts negative counts if V-E<=1. Watchdog literal repeated strings/spacing-sensitive Subst check is no general halting proof. Regge positive10edges and sum>=10 proxy plus supplied Bianchi sum ignores deficits, admits impossible metric and rejects small valid regular simplex. Fuzzer runs25cases/level, with levels15/16/17 literally repeating identical input;12mutants are malformed inputs, not12mutated implementations. Aggregate100percent/zero-defect wording bounded to these generated examples. Pure selected-class countercontrols recorded separately, no original test runner executed.')
a.record(wp,1,628,'Full628line body read in two chunks. Scripted agents emit fixed data and use test-local evaluators; no model inference or independent agents. Frozen dataclass contains mutable dict; JSON fallback str erases types, turn hash only64bits and excludes claimed_status. History allocated but never updated/checked; parent hash linkage and roles/round/task sequence not enforced. Claimed four terminals include no OracleNeeded route. Gauge repair replaces cycle-sum3 cochain withzero, not an allowed coboundary (F015). Cochain path accepts missing/float/wrong-shape zero sums and asserts complementary slackness without dual data. Meron branch checks only whether bond list nonempty and labels sign problem quenched (F016). Authority branch ignores returned REFUSED receipt and certifies when status annotation removed, violating asserted deletion invariance (F017). Regge delegates to the proxy tester, trust in supplied sum persists. Five workflow assertions pass scripted expected labels; no true minimumL1 repair, physical meron result, retry-history guard, independent proof, 4D geometry or broad100percent fail-closed guarantee follows. Full original runners not executed; only read-vetted selected classes used in bounded controls.')
n=a.read('_notes.json');probe=a.read('_probe01.json');assert len(probe['results'])==15
ev=lambda p,s,e:{'path':p,'sha256':a.row(p)['sha256'],'lines':[s,e]}
defs=[
('gauge_shift_invariant','false_gauge_repair_certified',wp,194,219,['gauge_replacement'],'Gauge repair replaces a nonexact cochain with zero instead of preserving its cycle sum.','On triangle edges01,12,20 every d0(alpha) telescopes to cycle sum0. Supplied cochain sum3 cannot be changed to0 by a gauge shift. Claimed alpha gives residual(0,0,3), but repair hardcodes(0,0,0) and harness certifies.','medium'),
('meron_site_and_pair_binding','invalid_nonempty_bond_certified',wp,322,362,['invalid_meron_bond'],'Meron workflow certifies an invalid bond without computing clusters or signs.','Only len(bonds)==0 is checked; bond(-1,99) on declared sites0..3 reaches Certificate, meron_count0 and fermion_sign_problem_quenched=True. No pairing/involution/sector enumeration is performed.','medium'),
('deletion_invariance_return_handling','removing_status_changes_refusal_to_certificate',wp,307,320,['deletion_invariance'],'Removing the producer status converts an unverified refusal to a certificate.','Authority gate returns a REFUSED receipt for claimed_status=None with independent_verifier_passed=False; harness ignores the return and emits Certificate. CERTIFIED annotation instead raises and refuses. Same payload and same computed turn hash give different verdicts.','medium'),
('cochain_carrier_and_exactness','empty_float_and_wrong_dimension_certified',wp,266,305,['empty_float_cochains'],'Cochain dialogue certifies empty, float and wrong-dimension inputs from their scalar sum.','No carrier/incidence/type/length/primal-dual check precedes sum(cochain)==0. Missing cochain, [0.0], and two entries with noedges all produce Certificate with witness_verified=True.','medium'),
('bounded_ars_confluence','cyclic_nonjoinable_peak_and_cutoff_certified',ep,95,139,['ars_no_normal_forms','ars_cutoff_normal_form'],'Test-local confluence evaluator certifies nonjoinable cyclic branches and labels a depth cutoff a normal form.','For a→b,a→c,b→b,c→c, branch descendant sets{b} and{c} are disjoint; no normal form is found and evaluator certifies a. With a→b→c,max_depth0 it certifies reducible b as normal_form.','medium'),
('dda_complete_field_commitment','six_fields_mutated_without_rehash_and_certified',ep,147,213,['dda_unbound_fields'],'DDA hash does not bind six declared event fields or replay the event.','Changed redex position,cost,three defect values and stack depth retain the same hash and CERTIFIED receipt; negative cost/depth also pass. Six serialized fields plus previous hash do not commit to the whole13tuple; no rewrite replay or observation map supplied.','medium'),
('regge_geometry_and_scale','impossible_metric_certified_small_regular_metric_refused',ep,604,639,['regge_impossible_triangle','regge_small_regular_refusal'],'Regge proxy admits impossible triangle lengths and refuses a valid small regular simplex.','One squared edge100 and nine squared edges1 imply a triangle10>1+1; accepted when supplied bianchi_sum0, even with empty deficits. Allten squared lengths1/100 form a regular simplex after scaling, but sum<10 is rejected. Deficits never used.','medium'),
('hodge_subspace_membership','nonharmonic_vector_certified_as_harmonic',ep,458,509,['hodge_nonharmonic_vector','hodge_independent_chain'],'Hodge certificate checks orthogonal vectors without checking exact, coexact or harmonic subspaces.','Every vector can be put wholly in harmonic slot with other slots0 and gap0. For single-edge d0=[-1,1],d1=0, claimed harmonic[1] has Laplacian[2], yet accepted because no operators are input. This is not an LP solve.','medium'),
('ihara_graph_validity','negative_graph_counts_certified',ep,522,548,['ihara_invalid_counts'],'Ihara spectral monitor ignores eigenvalues and admits negative graph counts.','V=-3,E=-1 and arbitrary eigenvalue999 satisfy the sole V-E<=1 check and return CERTIFIED. Neither graph realization nor Bass-Ihara determinant is computed. Disconnected valid graphs can also have chi>1, absent a connectedness premise.','medium'),
('colimit_source_carrier','unknown_symbol_and_depth_ignored',ep,356,408,['ind_unknown_symbol'],'Colimit inclusion checks allow symbols outside every declared carrier.','Source{a},target{a,b},depth0 accepts twenty z characters because it only rejects symbols occurring in a known future difference. No source membership, depth or categorical universal property is checked.','medium'),
('alternation_input_and_budget','unknown_quantifier_negative_steps_certified',ep,228,257,['negative_budget_unknown_quantifier'],'Alternation supervisor accepts unknown quantifiers and negative budgets.','[NOT_A_QUANTIFIER],max_steps=-1,executed_steps=-2 returns CERTIFIED. Counter comparison is not budget enforcement or a proof of halting.','low'),
('self_reference_lexical_boundary','spaced_substitution_passes',ep,561,591,['spaced_self_substitution'],'Self-substitution detector misses the whitespace form printed in its own description.','Subst(T, x, T) lacks literal comma-x-comma and returns CERTIFIED; compact Subst(T,x,T) is the only tested pattern. Repeated text detection is also not proof that a semantic execution is infinite.','low')]
for i,(rule,status,path,start,end,keys,title,reason,severity) in enumerate(defs,12):
 cid=f'PFPTESTS-C{i:03d}';fid=f'PFPTESTS-F{i+3:03d}'
 evidence=[ev(path,start,end)]
 if rule=='deletion_invariance_return_handling':evidence.append(ev(ep,318,348))
 n['controls'].append({'id':cid,'rule':rule,'status':status,'source_evidence':evidence,'results':{k:probe['results'][k] for k in keys},'probe_path':'dag/reviews/additional_pfp_tests_remaining_probe01.json','probe_sha256':a.sha(a.file('_probe01.json')),'helper_sha256':a.sha(a.file('_probe01.py')),'method':probe['method']})
 n['findings'].append({'id':fid,'severity':severity,'statement':title,'evidence':evidence,'control':cid,'reason':reason,'limits':'This is the test-local evaluator/workflow harness, not a new finding against canonical production implementations. Bounded selected-class offline controls only; no broad suite/native/provider execution.'})
n['claims'].append({'id':'PFPTESTS-CL008','statement':'Levels11–21 and dialogue files implement self-contained toy checker substitutes; their successful labels do not establish canonical production correctness or the named broad mathematics.','evidence':[ev(ep,647,688),ev(ep,872,973),ev(wp,34,53),ev(wp,565,588)],'limits':'275constructed positive cases and12bad-input mutations are declared by loops; original runner not executed in this audit. Some positive loops repeat one literal case25times. Bounded controls expose false certificates in these local substitutes.'})
a.write('_notes.json',n);a.report()
